INSERT INTO `v1_eb2e4a41888c8abe85cbb691c8c1e18752332384ad7191a24cb6c07e9cf2a6f0` VALUES (0.0, 0.0, 0.0, 24001, "リン", "あたしだって\nやるときはやるよ！", "2030/12/17 14:59:59", 24, 0, 102601, "2020/04/30 12:00:00", 10040, 1, 1);
INSERT INTO `v1_eb2e4a41888c8abe85cbb691c8c1e18752332384ad7191a24cb6c07e9cf2a6f0` VALUES (0.0, 0.0, 0.0, 24002, "リン", "ふぅ…\nこれであたしの仕事は\n終わりだね", "2030/12/17 14:59:59", 24, 1, 102601, "2020/04/30 12:00:00", 10040, 1, 1);
INSERT INTO `v1_eb2e4a41888c8abe85cbb691c8c1e18752332384ad7191a24cb6c07e9cf2a6f0` VALUES (0.0, 0.0, 0.0, 24003, "リン", "終わった終わった\n一人でもなんとか\nなるもんだね", "2030/12/17 14:59:59", 24, 2, 102601, "2020/04/30 12:00:00", 10040, 1, 1);
INSERT INTO `v1_eb2e4a41888c8abe85cbb691c8c1e18752332384ad7191a24cb6c07e9cf2a6f0` VALUES (0.0, 0.0, 0.0, 24004, "リン", "やったね！\nこれでようやく\nサボれるよ…", "2030/12/17 14:59:59", 24, 3, 102601, "2020/04/30 12:00:00", 10040, 2, 2);
INSERT INTO `v1_eb2e4a41888c8abe85cbb691c8c1e18752332384ad7191a24cb6c07e9cf2a6f0` VALUES (0.0, 0.0, 0.0, 24005, "リン", "チーズが欲しいなら\nきちんと働いて\n買いに来なよ", "2030/12/17 14:59:59", 24, 4, 102601, "2020/04/30 12:00:00", 10040, 1, 1);
INSERT INTO `v1_eb2e4a41888c8abe85cbb691c8c1e18752332384ad7191a24cb6c07e9cf2a6f0` VALUES (0.0, 0.0, 0.0, 24006, "リン", "あたしを敵に回した\n恐ろしさ\n思い知ったか！", "2030/12/17 14:59:59", 24, 5, 102601, "2020/04/30 12:00:00", 10040, 2, 2);
INSERT INTO `v1_eb2e4a41888c8abe85cbb691c8c1e18752332384ad7191a24cb6c07e9cf2a6f0` VALUES (0.0, 0.0, 0.0, 24007, "リン", "あたしも意外と\nやるもんでしょ？", "2030/12/17 14:59:59", 24, 6, 102601, "2020/04/30 12:00:00", 10040, 2, 2);
INSERT INTO `v1_eb2e4a41888c8abe85cbb691c8c1e18752332384ad7191a24cb6c07e9cf2a6f0` VALUES (0.0, 0.0, 0.0, 24008, "リン", "疲れた…\nねずみの逃げ足\n速すぎるよ…", "2030/12/17 14:59:59", 24, 7, 102601, "2020/04/30 12:00:00", 10040, 4, 4);
INSERT INTO `v1_eb2e4a41888c8abe85cbb691c8c1e18752332384ad7191a24cb6c07e9cf2a6f0` VALUES (0.0, 0.0, 0.0, 24009, "リン", "このままじゃ\nまっひ～に\n叱られちゃうよ", "2030/12/17 14:59:59", 24, 8, 102601, "2020/04/30 12:00:00", 10040, 4, 4);
INSERT INTO `v1_eb2e4a41888c8abe85cbb691c8c1e18752332384ad7191a24cb6c07e9cf2a6f0` VALUES (0.0, 0.0, 0.0, 24010, "リン", "まじめに\nやったんだけどな…\n悔しいな～", "2030/12/17 14:59:59", 24, 9, 102601, "2020/04/30 12:00:00", 10040, 4, 4);
INSERT INTO `v1_eb2e4a41888c8abe85cbb691c8c1e18752332384ad7191a24cb6c07e9cf2a6f0` VALUES (0.0, 0.0, 0.0, 24011, "リン", "やられた…\nねずみって意外と\nてごわいね", "2030/12/17 14:59:59", 24, 10, 102601, "2020/04/30 12:00:00", 10040, 4, 4);
INSERT INTO `v1_eb2e4a41888c8abe85cbb691c8c1e18752332384ad7191a24cb6c07e9cf2a6f0` VALUES (0.0, 0.0, 0.0, 24012, "リン", "おのれ～\nあたしのチーズを\n盗みやがって～！", "2030/12/17 14:59:59", 24, 11, 102601, "2020/04/30 12:00:00", 10040, 4, 4);
INSERT INTO `v1_eb2e4a41888c8abe85cbb691c8c1e18752332384ad7191a24cb6c07e9cf2a6f0` VALUES (1.81, 0.0, 0.0, 24013, "リン", "疲れた…\nけど、次こそは\n守り抜くよ…", "2030/12/17 14:59:59", 24, 12, 102601, "2020/04/30 12:00:00", 10040, 4, 1);
